Lemma wordToNat_err_partition_overlap :
  wordToNat ERR_PARTITION_OVERLAP_VAL = KAMI_ERR_PARTITION_OVERLAP.
Proof.
  unfold KAMI_ERR_PARTITION_OVERLAP. destruct kami_err_partition_overlap_witness as [n E].
  cbn [proj1_sig]. subst n. rewrite <- N_to_nat_wordToN. f_equal; vm_compute; reflexivity.
Qed.

Theorem step_pnew_refines : forall a0 a1 a2 a3 a4 a5 a6 a7 b0 b1 b2 b3 b4 b5 b6 b7 c0 c1 c2 c3 c4 c5 c6 c7 (b : HWB) (region : list nat),
