  wordToNat (hw_trap_vector b) = LASSERT_TRAP_PC ->
  hwb_snapshot (step_next b) = kami_step (hwb_snapshot b) (instr_pnew region (wordToNat (bits8 c0 c1 c2 c3 c4 c5 c6 c7))).
